type Role="customer"|"merchant"|"driver"|"admin";
type Kind="ride"|"delivery";
type Service="package";
type Job={id:string;kind:Kind;service:Service;pickup:string;destination:string;price:number;commission:number;driverPayout:number;distance:number;status:string;trackingToken?:string;driverId?:string|null;createdAt:string;customerName?:string;customerPhone?:string;senderName?:string;senderPhone?:string;recipientName?:string;recipientPhone?:string;packageType?:string;trackingCode?:string;pickupLat?:number|null;pickupLng?:number|null;destinationLat?:number|null;destinationLng?:number|null;raw:any};
type Region={latitude:number;longitude:number;latitudeDelta:number;longitudeDelta:number};
const APP_ROLE=String(Constants.expoConfig?.extra?.appRole||"all");
const MAP_STYLE="https://tiles.openfreemap.org/styles/liberty";
const GREEN="#E52B45",INK="#25252B",MUTED="#777780",BG="#F7F7F9",LINE="#E9E9ED";
const COTUI={latitude:19.0527,longitude:-70.1494};
const INITIAL:Region={...COTUI,latitudeDelta:.025,longitudeDelta:.025};
const money=(v:number)=>"RD$"+Math.round(v||0).toLocaleString("es-DO");
const statusText=(s:string)=>({requested:"Buscando repartidor",accepted:"Repartidor asignado",courier_arriving:"Repartidor llegando",driver_arriving:"Conductor en camino",in_progress:"Servicio en curso",picked_up:"Paquete recogido",on_the_way:"Paquete en camino",completed:"Servicio completado",delivered:"Entrega completada",cancelled:"Cancelado"} as Record<string,string>)[s]||s;
function parseSharedDeliveryText(raw:string){
 let value=raw;try{value=decodeURIComponent(raw.replace(/&amp;/g,"&"));}catch{}
 const patterns=[/[?&](?:q|query|ll|center)=(-?\d{1,2}(?:\.\d+)?)[,%20+\s]+(-?\d{1,3}(?:\.\d+)?)/i,/geo:(-?\d{1,2}(?:\.\d+)?),(-?\d{1,3}(?:\.\d+)?)/i,/@(-?\d{1,2}(?:\.\d+)?),(-?\d{1,3}(?:\.\d+)?)/i,/!3d(-?\d{1,2}(?:\.\d+)?)!4d(-?\d{1,3}(?:\.\d+)?)/i];
 let coordinates:MapCoordinate|null=null;
 for(const pattern of patterns){const match=value.match(pattern);if(match){const latitude=Number(match[1]),longitude=Number(match[2]);if(Math.abs(latitude)<=90&&Math.abs(longitude)<=180){coordinates={latitude,longitude};break;}}}
 const recipientName=value.match(/(?:destinatario|recibe|nombre)\s*[:\-]\s*([^\n,]+)/i)?.[1]?.trim()||"";
 const recipientPhone=value.match(/(?:\+?1[\s.-]?)?(?:809|829|849)[\s.-]?\d{3}[\s.-]?\d{4}/)?.[0]||"";
 const address=value.match(/(?:dirección|ubicación|referencia)\s*[:\-]\s*([^\n]+)/i)?.[1]?.trim()||"";
 return {coordinates,recipientName,recipientPhone,address};
}
const kmBetween=(a:any,b:any)=>{const rad=(v:number)=>v*Math.PI/180;const d1=rad(b.latitude-a.latitude),d2=rad(b.longitude-a.longitude);const h=Math.sin(d1/2)**2+Math.cos(rad(a.latitude))*Math.cos(rad(b.latitude))*Math.sin(d2/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));};
function mapRide(x:any):Job{return {id:x.id,kind:"ride",service:"moto",pickup:x.pickup_address,destination:x.destination_address,price:Number(x.agreed_fee_dop??x.estimated_fare_dop??0),commission:Number(x.platform_commission_dop??0),driverPayout:Number(x.driver_payout_dop??0),distance:Number(x.distance_km??0),status:x.status,trackingToken:x.tracking_token,driverId:x.driver_id,createdAt:x.created_at,customerName:x.customer_name,customerPhone:x.customer_phone,pickupLat:x.pickup_lat,pickupLng:x.pickup_lng,destinationLat:x.destination_lat,destinationLng:x.destination_lng,raw:x};}
function mapDelivery(x:any):Job{return {id:x.id,kind:"delivery",service:"package",pickup:x.pickup_address,destination:x.delivery_address,price:Number(x.agreed_fee_dop??x.estimated_fee_dop??0),commission:Number(x.platform_commission_dop??0),driverPayout:Number(x.driver_payout_dop??0),distance:Number(x.distance_km??0),status:x.status,trackingToken:x.tracking_token,driverId:x.courier_id,createdAt:x.created_at,senderName:x.sender_name,senderPhone:x.sender_phone,recipientName:x.recipient_name,recipientPhone:x.recipient_phone,packageType:x.package_type,trackingCode:x.tracking_code,pickupLat:x.pickup_lat,pickupLng:x.pickup_lng,destinationLat:x.destination_lat,destinationLng:x.destination_lng,raw:x};}

export default function App(){
 const {hasShareIntent,shareIntent,resetShareIntent}=useShareIntent();
 const [role,setRole]=useState<Role>(APP_ROLE==="business"?"merchant":APP_ROLE==="delivery"?"driver":"customer"),[tab,setTab]=useState("Inicio"),[service,setService]=useState<Service>("package");
 const [region,setRegion]=useState<Region>(INITIAL),[origin,setOrigin]=useState(COTUI),[destination,setDestination]=useState<any>(null),[driverPoint,setDriverPoint]=useState<any>(null);
 const [pickup,setPickup]=useState("Mi ubicación actual"),[dropoff,setDropoff]=useState("Mantén presionado el mapa para marcar destino");
 const [name,setName]=useState(""),[phone,setPhone]=useState(""),[recipient,setRecipient]=useState(""),[recipientPhone,setRecipientPhone]=useState(""),[packageType,setPackageType]=useState("paquete"),[details,setDetails]=useState("");
 const [email,setEmail]=useState(""),[password,setPassword]=useState(""),[session,setSession]=useState<any>(null),[profile,setProfile]=useState<any>(null),[driver,setDriver]=useState<any>(null),[merchant,setMerchant]=useState<any>(null),[sharedMessage,setSharedMessage]=useState("");
 const [jobs,setJobs]=useState<Job[]>([]),[active,setActive]=useState<Job|null>(null),[activeToken,setActiveToken]=useState(""),[liveTrip,setLiveTrip]=useState<any>(null);
 const [quote,setQuote]=useState<any>(null),[busy,setBusy]=useState(false),[online,setOnline]=useState(false),[pin,setPin]=useState("");
 const [wallet,setWallet]=useState<any>(null),[topups,setTopups]=useState<any[]>([]),[pendingTopups,setPendingTopups]=useState<any[]>([]),[pricing,setPricing]=useState<any>(null),[adminStats,setAdminStats]=useState({rides:0,deliveries:0,drivers:0,active:0,revenue:0}),[topupAmount,setTopupAmount]=useState("500"),[topupMethod,setTopupMethod]=useState("transferencia"),[topupReference,setTopupReference]=useState("");
 const straightKm=useMemo(()=>destination?kmBetween(origin,destination):0,[origin,destination]);
 const screenMotion=useRef(new Animated.Value(0)).current;
 useEffect(()=>{screenMotion.setValue(0);Animated.timing(screenMotion,{toValue:1,duration:300,easing:Easing.out(Easing.cubic),useNativeDriver:true}).start();},[role,tab,screenMotion]);

 useEffect(()=>{(async()=>{try{const {data}=await supabase.auth.getSession();setSession(data.session);if(data.session?.user){setName(data.session.user.user_metadata?.full_name||"");setPhone(data.session.user.user_metadata?.phone||"");}}catch{}try{const p=await Location.requestForegroundPermissionsAsync();if(p.status==="granted"){const pos=await Location.getCurrentPositionAsync({accuracy:Location.Accuracy.Balanced});const c={latitude:pos.coords.latitude,longitude:pos.coords.longitude};setOrigin(c);setRegion({...c,latitudeDelta:.018,longitudeDelta:.018});}}catch{}})();},[]);
 useEffect(()=>{if(!hasShareIntent)return;const raw=String(shareIntent?.text||shareIntent?.webUrl||"").trim();if(!raw)return;const parsed=parseSharedDeliveryText(raw);setRole("merchant");setService("package");setTab("Inicio");setSharedMessage(raw);setQuote(null);if(parsed.coordinates){setDestination(parsed.coordinates);setDropoff(parsed.address||"Ubicación detectada · confirma el punto en el mapa");}else if(parsed.address){setDropoff(parsed.address);}else{setDropoff("Ubicación recibida · marca el punto exacto en el mapa");}if(parsed.recipientName)setRecipient(parsed.recipientName);if(parsed.recipientPhone)setRecipientPhone(parsed.recipientPhone);resetShareIntent();Alert.alert("Datos recibidos","Cotuí Go preparó el envío. Revisa la ubicación y completa solo lo que falte.");},[hasShareIntent,shareIntent?.text,shareIntent?.webUrl]);
 useEffect(()=>{if(session?.user?.id&&configured)loadIdentity();else{setProfile(null);setDriver(null);}},[session]);
 useEffect(()=>{if(!configured||!session?.user?.id)return;loadJobs();const ch=supabase.channel("cg-native-requests").on("postgres_changes",{event:"*",schema:"public",table:"cg_ride_requests"},()=>loadJobs()).on("postgres_changes",{event:"*",schema:"public",table:"cg_delivery_requests"},()=>loadJobs()).subscribe();const poll=setInterval(()=>void loadJobs(),5000);return()=>{clearInterval(poll);supabase.removeChannel(ch)};},[session,role,driver?.id]);
 useEffect(()=>{if(!activeToken||!configured)return;let alive=true;const load=async()=>{const {data,error}=await supabase.rpc("cg_get_public_trip",{p_token:activeToken});if(!error&&alive&&data){setLiveTrip(data);if(data.driver_lat!=null&&data.driver_lng!=null)setDriverPoint({latitude:data.driver_lat,longitude:data.driver_lng});}};void load();const poll=setInterval(()=>void load(),3500);const ch=supabase.channel("trip:"+activeToken,{config:{private:false}}).on("broadcast",{event:"driver_location"},({payload})=>{if(alive){setLiveTrip((v:any)=>v?({...v,...payload}):payload);if(payload.driver_lat!=null)setDriverPoint({latitude:payload.driver_lat,longitude:payload.driver_lng});}}).on("broadcast",{event:"trip_status"},({payload})=>{if(alive)setLiveTrip((v:any)=>v?({...v,...payload}):payload);void load();}).subscribe();return()=>{alive=false;clearInterval(poll);supabase.removeChannel(ch)};},[activeToken]);
 useEffect(()=>{if(role!=="driver"||!driver?.id||!online)return;let sub:Location.LocationSubscription|null=null;(async()=>{try{sub=await Location.watchPositionAsync({accuracy:Location.Accuracy.High,distanceInterval:12,timeInterval:6000},async p=>{const coords={current_lat:p.coords.latitude,current_lng:p.coords.longitude,last_location_at:new Date().toISOString()};setDriverPoint({latitude:coords.current_lat,longitude:coords.current_lng});await supabase.from("cg_driver_profiles").update(coords).eq("id",driver.id);});}catch{}})();return()=>sub?.remove();},[role,driver?.id,online]);

 async function loadIdentity(){const uid=session.user.id;const {data:p}=await supabase.from("profiles").select("*").eq("id",uid).maybeSingle();setProfile(p);if(p?.full_name)setName(p.full_name);if(p?.phone)setPhone(p.phone);const {data:d}=await supabase.from("cg_driver_profiles").select("*").eq("user_id",uid).maybeSingle();setDriver(d);if(d){setOnline(!!d.is_available);if(APP_ROLE!=="delivery"){const {data:w}=await supabase.from("cg_driver_wallets").select("*").eq("driver_id",d.id).maybeSingle();setWallet(w);}else setWallet(null);}const {data:m}=await supabase.from("merchants").select("id,store_name,status").eq("owner_id",uid).maybeSingle();setMerchant(m||null);if(m?.store_name)setName(m.store_name);const {data:admin}=await supabase.rpc("cg_is_admin");if(admin===true)setRole("admin");else if(APP_ROLE==="business")setRole("merchant");else if(APP_ROLE==="delivery")setRole("driver");else if(d?.status==="approved")setRole("driver");else if(m?.status==="active")setRole("merchant");else setRole("customer");}
 async function loadJobs(){if(!session?.user?.id)return;const uid=session.user.id;let rides:any[]=[];let deliveries:any[]=[];if(role==="admin"){const [r,d]=await Promise.all([supabase.from("cg_ride_requests").select("*").order("created_at",{ascending:false}).limit(80),supabase.from("cg_delivery_requests").select("*").order("created_at",{ascending:false}).limit(80)]);rides=r.data||[];deliveries=d.data||[];}else if(role==="driver"&&driver?.id){const [r,d]=await Promise.all([supabase.from("cg_ride_requests").select("*").or("status.eq.requested,driver_id.eq."+driver.id).order("created_at",{ascending:false}).limit(80),supabase.from("cg_delivery_requests").select("*").or("status.eq.requested,courier_id.eq."+driver.id).order("created_at",{ascending:false}).limit(80)]);rides=r.data||[];deliveries=d.data||[];}else if(role==="merchant"){const {data:d}=await supabase.from("cg_delivery_requests").select("*").eq("customer_id",uid).order("created_at",{ascending:false}).limit(80);deliveries=d||[];}else{const [r,d]=await Promise.all([supabase.from("cg_ride_requests").select("*").eq("customer_id",uid).order("created_at",{ascending:false}).limit(50),supabase.from("cg_delivery_requests").select("*").eq("customer_id",uid).order("created_at",{ascending:false}).limit(50)]);rides=r.data||[];deliveries=d.data||[];}
 const all=deliveries.map(mapDelivery).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));setJobs(all);if(role==="driver"&&driver?.id&&APP_ROLE!=="delivery"){const [w,tp]=await Promise.all([supabase.from("cg_driver_wallets").select("*").eq("driver_id",driver.id).maybeSingle(),supabase.from("cg_wallet_topups").select("*").eq("driver_id",driver.id).order("created_at",{ascending:false}).limit(8)]);setWallet(w.data);setTopups(tp.data||[]);}if(role==="admin"){const [dr,pr]=await Promise.all([supabase.from("cg_driver_profiles").select("id"),supabase.rpc("cg_get_pricing_settings")]);const activeCount=all.filter(x=>!["completed","delivered","cancelled"].includes(x.status)).length;setAdminStats({rides:rides.length,deliveries:deliveries.length,drivers:dr.data?.length||0,active:activeCount,revenue:all.reduce((n,x)=>n+x.commission,0)});if(pr.data)setPricing(pr.data);const {data:t}=await supabase.from("cg_wallet_topups").select("*,cg_driver_profiles(full_name,phone)").eq("status","pending").order("created_at",{ascending:false});setPendingTopups(t||[]);}}
 async function signIn(){if(!configured){Alert.alert("Backend pendiente","Configura Supabase antes de iniciar sesión.");return;}if(!email||!password)return Alert.alert("Completa tus datos","Escribe correo y contraseña.");setBusy(true);const {data,error}=await supabase.auth.signInWithPassword({email,password});setBusy(false);if(error)Alert.alert("No se pudo entrar",error.message);else setSession(data.session);}
 async function signUp(){if(!configured){Alert.alert("Backend pendiente","Configura Supabase para registrar cuentas.");return;}if(!email||password.length<8||!name||!phone){Alert.alert("Datos incompletos","Completa nombre, teléfono, correo y una contraseña de 8 caracteres.");return;}setBusy(true);const {data,error}=await supabase.auth.signUp({email,password,options:{data:{full_name:name,phone}}});setBusy(false);if(error)Alert.alert("No se pudo registrar",error.message);else Alert.alert("Cuenta creada","Revisa tu correo si la confirmación está activada.");}
 async function signOut(){await supabase.auth.signOut();setSession(null);setRole("customer");setTab("Inicio");setJobs([]);setActive(null);}
 async function getQuote(){if(!destination)throw new Error("Marca el destino en el mapa.");let routeDistance:number|null=null;try{const url="https://router.project-osrm.org/route/v1/driving/"+origin.longitude+","+origin.latitude+";"+destination.longitude+","+destination.latitude+"?overview=false&steps=false";const response=await fetch(url);if(response.ok){const result=await response.json();const meters=result?.routes?.[0]?.distance;if(typeof meters==="number"&&meters>0)routeDistance=meters/1000;}}catch{}const {data,error}=await supabase.rpc("cg_quote_fare",{p_service:service,p_pickup_lat:origin.latitude,p_pickup_lng:origin.longitude,p_destination_lat:destination.latitude,p_destination_lng:destination.longitude,p_route_distance_km:routeDistance});if(error)throw error;setQuote(data);return data;}
 async function createRequest(){if(!configured){Alert.alert("Conecta Supabase","El modo real necesita las credenciales del backend.");return;}if(!session){Alert.alert("Inicia sesión","Crea tu cuenta para solicitar el servicio.");setTab("Cuenta");return;}if(!destination){Alert.alert("Selecciona el destino","Mantén presionado el mapa donde quieres llegar.");return;}if(!name.trim()||!phone.trim()){Alert.alert("Completa tus datos","Indica tu nombre y teléfono.");return;}if(service==="package"&&(!recipient.trim()||!recipientPhone.trim())){Alert.alert("Datos del destinatario","Completa quién recibe el paquete y su teléfono.");return;}setBusy(true);try{const q=quote||await getQuote();const {error:profileError}=await supabase.from("profiles").update({full_name:name,phone}).eq("id",session.user.id);if(profileError)throw profileError;const {data,error}=await supabase.from("cg_delivery_requests").insert({distance_km:q.distance_km,customer_id:session.user.id,sender_name:name,sender_phone:phone,recipient_name:recipient,recipient_phone:recipientPhone,pickup_address:pickup,delivery_address:dropoff,package_type:packageType,service_kind:"package",package_description:details||null,pickup_lat:origin.latitude,pickup_lng:origin.longitude,destination_lat:destination.latitude,destination_lng:destination.longitude}).select("tracking_token").single();if(error)throw error;const token=data.tracking_token;const kind:Kind="delivery";if(!token)throw new Error("La solicitud se creó sin código de seguimiento.");setActiveToken(token);setLiveTrip({kind,status:"requested",pickup_address:pickup,destination_address:dropoff,pickup_lat:origin.latitude,pickup_lng:origin.longitude,destination_lat:destination.latitude,destination_lng:destination.longitude});setQuote(null);setTab("Actividad");setDropoff("Mantén presionado el mapa para marcar destino");setDestination(null);setDetails("");await loadJobs();}catch(e){Alert.alert("No se pudo solicitar",e instanceof Error?e.message:"Intenta nuevamente.");}finally{setBusy(false);}}
 async function changeAvailability(){if(!driver)return;setBusy(true);try{let coords:any={};if(!online){const p=await Location.getCurrentPositionAsync({accuracy:Location.Accuracy.High});coords={current_lat:p.coords.latitude,current_lng:p.coords.longitude,last_location_at:new Date().toISOString()};}const {data,error}=await supabase.from("cg_driver_profiles").update({is_available:!online,...coords,updated_at:new Date().toISOString()}).eq("id",driver.id).select("*").single();if(error)throw error;setDriver(data);setOnline(!!data.is_available);}catch(e){Alert.alert("No se pudo cambiar disponibilidad",e instanceof Error?e.message:"Intenta otra vez.");}finally{setBusy(false);}}
 async function accept(job:Job){if(!driver)return;setBusy(true);const {error}=await supabase.rpc(job.kind==="ride"?"cg_driver_accept_ride":"cg_driver_accept_delivery",job.kind==="ride"?{p_ride_id:job.id}:{p_delivery_id:job.id});setBusy(false);if(error){Alert.alert("No se pudo aceptar",error.message);return;}await loadJobs();Alert.alert("Servicio asignado","Revisa la recogida y navega hacia el punto.");}
 async function advance(job:Job,next:string){setBusy(true);let error:any=null;if(job.kind==="ride"&&next==="in_progress"){const r=await supabase.rpc("cg_driver_start_ride",{p_ride_id:job.id,p_pin:pin});error=r.error;if(!error&&r.data!==true)error=new Error("PIN incorrecto o bloqueado. Verifica el código con el cliente.");}else{const r=await supabase.rpc(job.kind==="ride"?"cg_driver_update_ride_status":"cg_driver_update_delivery_status",job.kind==="ride"?{p_ride_id:job.id,p_status:next}:{p_delivery_id:job.id,p_status:next});error=r.error;}setBusy(false);if(error){Alert.alert("No se pudo actualizar",error.message);return;}setPin("");await loadJobs();}
 async function requestWalletTopup(){const amount=Number(topupAmount);if(!Number.isFinite(amount)||amount<100||amount>100000){Alert.alert("Monto inválido","La recarga debe ser entre RD$100 y RD$100,000.");return;}setBusy(true);const {error}=await supabase.rpc("cg_driver_request_wallet_topup",{p_amount:amount,p_payment_method:topupMethod,p_payment_reference:topupReference||null,p_driver_note:null});setBusy(false);if(error)Alert.alert("No se pudo solicitar",error.message);else{setTopupReference("");Alert.alert("Solicitud enviada","Administración verificará el depósito antes de acreditar tu balance.");await loadJobs();}}
 async function reviewTopup(id:string,approve:boolean){setBusy(true);const {error}=await supabase.rpc("cg_admin_review_wallet_topup",{p_topup_id:id,p_approve:approve,p_admin_note:null});setBusy(false);if(error)Alert.alert("No se pudo revisar",error.message);else{Alert.alert("Solicitud actualizada",approve?"Recarga aprobada.":"Recarga rechazada.");await loadJobs();}}
 async function switchRole(r:Role){if(r==="customer"){setRole(r);setTab("Inicio");await loadJobs();return;}if(r==="merchant"&&(!session||!merchant||merchant.status!=="active")){Alert.alert("Cuenta de negocio","Inicia sesión con una cuenta de comercio aprobada para utilizar Cotuí Go Negocios.");return;}if(r==="driver"&&!driver){Alert.alert("Cuenta de repartidor","Esta cuenta no tiene una solicitud de repartidor registrada.");return;}if(r==="driver"&&driver.status!=="approved"){Alert.alert("Cuenta pendiente","Tu cuenta de repartidor todavía no está aprobada.");return;}if(r==="admin"){const {data,error}=await supabase.rpc("cg_is_admin");if(error||data!==true){Alert.alert("Acceso restringido","Esta cuenta no tiene permisos de administración.");return;}}setRole(r);setTab("Inicio");if(r==="merchant")setService("package");await loadJobs();}
 const pending=jobs.filter(j=>j.kind==="delivery"&&j.status==="requested"),mine=jobs.filter(j=>j.kind==="delivery"&&j.driverId===driver?.id),customerJobs=jobs.filter(j=>j.kind==="delivery"&&j.status!=="cancelled");
 const activeJob=active||customerJobs[0]||null;
 const mapRegion=destination?{latitude:(origin.latitude+destination.latitude)/2,longitude:(origin.longitude+destination.longitude)/2,latitudeDelta:Math.max(.012,Math.abs(origin.latitude-destination.latitude)*2.2),longitudeDelta:Math.max(.012,Math.abs(origin.longitude-destination.longitude)*2.2)}:region;

 return <SafeAreaView style={s.safe}><Animated.View style={{flex:1,opacity:screenMotion,transform:[{translateY:screenMotion.interpolate({inputRange:[0,1],outputRange:[10,0]})}]}}><View style={s.header}><View style={s.brandRow}><View style={s.logo}><Text style={s.logoText}>C</Text></View><View><Text style={s.brand}>Cotuí <Text style={{color:GREEN}}>Go</Text></Text><Text style={s.tagline}>Tu ciudad, en movimiento</Text></View></View><Pressable onPress={()=>setTab("Cuenta")} style={s.avatar}><Text style={s.avatarText}>{session?.user?.email?.[0]?.toUpperCase()||"G"}</Text></Pressable></View>
 {APP_ROLE==="all"&&<View style={s.roles}>{(["customer","merchant","driver","admin"] as Role[]).map(r=><Pressable key={r} onPress={()=>switchRole(r)} style={[s.roleBtn,role===r&&s.roleOn]}><Text style={[s.roleLabel,role===r&&s.roleLabelOn]}>{r==="customer"?"Cliente":r==="merchant"?"Negocio":r==="driver"?"Delivery":"Admin"}</Text></Pressable>)}</View>}

 {role==="merchant"&&<View style={{flex:1}}>{tab==="Inicio"&&<ScrollView contentContainerStyle={s.content} showsVerticalScrollIndicator={false}><View style={s.hero}><View><Text style={s.eyebrow}>COTUÍ GO · NEGOCIOS</Text><Text style={s.heroTitle}>Envía sin complicarte.</Text><Text style={s.heroSub}>Comparte desde WhatsApp y prepara tu envío en segundos.</Text></View><Text style={s.heroArt}>📦</Text></View><View style={s.panel}><Text style={s.panelTitle}>1. Comparte la ubicación del cliente</Text><Text style={s.helper}>En WhatsApp, comparte la ubicación o el mensaje con Cotuí Go. Si el nombre y teléfono están en mensajes separados, compártelos también. También puedes marcar el destino directamente en el mapa.</Text>{sharedMessage?<View style={{backgroundColor:"#F0F7F3",padding:11,borderRadius:10}}><Text style={s.eyebrow}>CONTENIDO RECIBIDO</Text><Text style={s.helper} numberOfLines={3}>{sharedMessage}</Text></View>:<Text style={s.helper}>Todavía no has compartido una ubicación.</Text>}<View style={s.mapWrap}><MapCanvas style={s.map} center={mapRegion} markers={[{coordinate:origin,title:"Tu negocio",color:GREEN},...(destination?[{coordinate:destination,title:"Cliente",color:"#E9A23B"}]:[])]} onLongPress={point=>{setDestination(point);setDropoff(point.latitude.toFixed(5)+", "+point.longitude.toFixed(5));setQuote(null);}}/><View style={s.mapLabel}><View style={s.dot}/><Text style={s.mapLabelText}>Mantén pulsado para ajustar la ubicación del cliente</Text></View></View><Text style={s.panelTitle}>2. Confirma los datos</Text><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={name} onChangeText={setName} placeholder="Nombre del negocio o remitente"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={phone} onChangeText={setPhone} placeholder="Teléfono del negocio" keyboardType="phone-pad"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={pickup} onChangeText={setPickup} placeholder="Dirección del negocio o punto de recogida"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={recipient} onChangeText={setRecipient} placeholder="Nombre de quien recibe"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={recipientPhone} onChangeText={setRecipientPhone} placeholder="Teléfono del destinatario" keyboardType="phone-pad"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={dropoff} onChangeText={setDropoff} placeholder="Dirección o referencia de entrega"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={details} onChangeText={setDetails} placeholder="Descripción del paquete (opcional)"/><View style={s.priceRow}><View><Text style={s.priceCaption}>Precio estimado</Text><Text style={s.price}>{quote?money(Number(quote.fare_dop)):"Por calcular"}</Text></View><Pressable style={s.quoteBtn} onPress={async()=>{try{await getQuote();}catch(e){Alert.alert("Falta ubicación",e instanceof Error?e.message:"Marca el destino en el mapa.");}}}><Text style={s.quoteText}>Calcular tarifa</Text></Pressable></View>{quote&&<Text style={s.helper}>{Number(quote.distance_km).toFixed(1)} km · Repartidor recibe {money(Number(quote.driver_payout_dop))}</Text>}<Pressable disabled={busy} onPress={createRequest} style={[s.primary,busy&&{opacity:.6}]}>{busy?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>Solicitar delivery →</Text>}</Pressable><Text style={s.smallCenter}>Verifica siempre el pin y los datos antes de enviar.</Text></View></ScrollView>}{tab==="Actividad"&&<ScrollView contentContainerStyle={s.content}><Text style={s.title}>Mis envíos</Text>{customerJobs.length===0?<Empty title="Aún no tienes envíos" body="Los paquetes que solicites aparecerán aquí."/>:customerJobs.map(j=><JobTile key={j.id} job={j} onPress={()=>{setActive(j);if(j.trackingToken)setActiveToken(j.trackingToken);}}/> )}</ScrollView>}{tab==="Cuenta"&&<AuthPanel name={name} setName={setName} phone={phone} setPhone={setPhone} email={email} setEmail={setEmail} password={password} setPassword={setPassword} onSignIn={signIn} onSignUp={signUp} onSignOut={signOut} session={session} busy={busy}/>}<Bottom items={["Inicio","Actividad","Cuenta"]} active={tab} onChange={setTab}/></View>}
 {role==="customer"&&<View style={{flex:1}}>{tab==="Inicio"&&<ScrollView contentContainerStyle={s.content} showsVerticalScrollIndicator={false}>
 <View style={s.hero}><View><Text style={s.eyebrow}>COTUÍ Y ZONAS CERCANAS</Text><Text style={s.heroTitle}>¿Qué enviamos por ti hoy?</Text><Text style={s.heroSub}>Solicita fácil. Sigue tu servicio en vivo.</Text></View><Text style={s.heroArt}>↗</Text></View>
 <View style={s.mapWrap}><MapCanvas style={s.map} center={mapRegion} markers={[{coordinate:origin,title:"Recogida",color:GREEN},...(destination?[{coordinate:destination,title:"Destino",color:"#E9A23B"}]:[])]} onLongPress={c=>{setDestination(c);setDropoff(c.latitude.toFixed(5)+", "+c.longitude.toFixed(5));setQuote(null);}}/><View style={s.mapLabel}><View style={s.dot}/><Text style={s.mapLabelText}>Mapa de Cotuí · Mantén presionado para elegir destino</Text></View><Pressable style={s.locate} onPress={async()=>{try{const p=await Location.getCurrentPositionAsync({});const c={latitude:p.coords.latitude,longitude:p.coords.longitude};setOrigin(c);setRegion({...c,latitudeDelta:.014,longitudeDelta:.014});setPickup("Mi ubicación actual");setQuote(null);}catch{Alert.alert("Ubicación no disponible","Activa el permiso de ubicación.");}}}><Text style={{fontSize:20}}>◎</Text></Pressable></View>
 <Text style={s.section}>Elige el servicio</Text><View style={s.serviceRow}><Pressable onPress={()=>{setService("package");setQuote(null);}} style={[s.serviceCard,s.selected]}><Text style={s.serviceEmoji}>📦</Text><Text style={s.serviceTitle}>Paquetería</Text><Text style={s.serviceDesc}>Envía y recibe entregas en Cotuí</Text></Pressable></View>
 <View style={s.panel}><Text style={s.panelTitle}>Enviar un paquete</Text><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={name} onChangeText={setName} placeholder="Tu nombre"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={phone} onChangeText={setPhone} placeholder="Tu teléfono" keyboardType="phone-pad"/><View style={s.addressRow}><Text style={s.greenPin}>●</Text><TextInput style={s.addressInput} placeholderTextColor="#667085" selectionColor={GREEN} value={pickup} editable={false} placeholder="Punto de recogida"/></View><View style={s.addressLine}/><View style={s.addressRow}><Text style={s.orangePin}>●</Text><Text style={s.addressText} numberOfLines={2}>{dropoff}</Text></View>
 {service==="package"&&<><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={recipient} onChangeText={setRecipient} placeholder="Nombre de quien recibe"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={recipientPhone} onChangeText={setRecipientPhone} placeholder="Teléfono del destinatario" keyboardType="phone-pad"/><View style={{gap:8}}><Text style={s.fieldLabel}>Tipo de envío</Text><View style={s.packageChoices}>{[["paquete","Paquete"],["comida","Comida"],["compra","Compra"],["documento","Documento"],["farmacia","Farmacia"],["otro","Otro"]].map(([value,label])=><Pressable key={value} onPress={()=>setPackageType(value)} style={[s.packageChoice,packageType===value&&s.packageChoiceOn]}><Text style={[s.packageChoiceText,packageType===value&&s.packageChoiceTextOn]}>{label}</Text></Pressable>)}</View></View></>}
 <TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={details} onChangeText={setDetails} placeholder="Descripción del paquete (opcional)"/>
 <View style={s.priceRow}><View><Text style={s.priceCaption}>Tarifa estimada · {quote?.distance_km?Number(quote.distance_km).toFixed(1)+" km":destination?straightKm.toFixed(1)+" km aprox.":"marca destino"}</Text><Text style={s.price}>{quote?money(Number(quote.fare_dop)):"Por calcular"}</Text></View><Pressable style={s.quoteBtn} onPress={async()=>{try{await getQuote();}catch(e){Alert.alert("No se pudo calcular",e instanceof Error?e.message:"Marca recogida y destino.");}}}><Text style={s.quoteText}>Calcular tarifa</Text></Pressable></View>
 {quote&&<Text style={s.helper}>Comisión de plataforma: {quote.commission_pct}% · Ganancia del conductor: {money(Number(quote.driver_payout_dop))}</Text>}
 <Pressable disabled={busy} onPress={createRequest} style={[s.primary,busy&&{opacity:.6}]}>{busy?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>Solicitar servicio  →</Text>}</Pressable><Text style={s.smallCenter}>Tarifa calculada con las reglas activas de Cotuí Go.</Text></View>
 </ScrollView>}
 {tab==="Actividad"&&<ScrollView contentContainerStyle={s.content}><Text style={s.title}>Tu actividad</Text><Text style={s.subtitle}>Estado actualizado automáticamente.</Text>{customerJobs.length===0?<Empty title="Todavía no tienes servicios" body="Cuando solicites una moto o envío aparecerá aquí."/>:customerJobs.map(j=><JobTile key={j.id} job={j} onPress={()=>{setActive(j);if(j.trackingToken)setActiveToken(j.trackingToken);}}/>)}{activeToken&&<View style={s.panel}><Text style={s.panelTitle}>Seguimiento en vivo</Text><Text style={s.status}>{statusText(liveTrip?.status||activeJob?.status||"requested")}</Text><Text style={s.helper}>{liveTrip?.driver_name||"Buscando conductor cercano…"}</Text><Text style={s.helper}>{liveTrip?.pickup_address||activeJob?.pickup} → {liveTrip?.destination_address||activeJob?.destination}</Text>{liveTrip?.pickup_lat!=null&&<View style={s.liveMap}><MapCanvas style={s.map} center={{latitude:liveTrip.driver_lat??liveTrip.pickup_lat,longitude:liveTrip.driver_lng??liveTrip.pickup_lng,latitudeDelta:.012,longitudeDelta:.012}} markers={[{coordinate:{latitude:liveTrip.pickup_lat,longitude:liveTrip.pickup_lng},title:"Recogida",color:GREEN},...(liveTrip.destination_lat!=null?[{coordinate:{latitude:liveTrip.destination_lat,longitude:liveTrip.destination_lng},title:"Destino",color:"#E9A23B"}]:[]),...(liveTrip.driver_lat!=null?[{coordinate:{latitude:liveTrip.driver_lat,longitude:liveTrip.driver_lng},title:"Tu conductor",color:"#246BFE"}]:[])]} route={liveTrip.driver_lat!=null?[{latitude:liveTrip.driver_lat,longitude:liveTrip.driver_lng},(["in_progress","on_the_way"].includes(liveTrip.status)?{latitude:liveTrip.destination_lat,longitude:liveTrip.destination_lng}:{latitude:liveTrip.pickup_lat,longitude:liveTrip.pickup_lng})]:undefined}/></View>}</View>}</ScrollView>}
 {tab==="Cuenta"&&<AuthPanel name={name} setName={setName} phone={phone} setPhone={setPhone} email={email} setEmail={setEmail} password={password} setPassword={setPassword} onSignIn={signIn} onSignUp={signUp} onSignOut={signOut} session={session} busy={busy}/>}
 <Bottom items={["Inicio","Actividad","Cuenta"]} active={tab} onChange={setTab}/></View>}

 {role==="driver"&&<View style={{flex:1}}>{tab==="Inicio"&&<ScrollView contentContainerStyle={s.content}><Text style={s.eyebrow}>CENTRO DE REPARTIDORES</Text><Text style={s.title}>{APP_ROLE==="delivery"?"Tus paquetes empiezan aquí":"Tu jornada empieza aquí"}</Text>{(!driver||driver.status!=="approved")&&<View style={s.panel}><Text style={s.panelTitle}>Activa tu cuenta de repartidor</Text><Text style={s.helper}>Para recibir paquetes, tu perfil y documentos deben ser revisados por Cotuí Go. Inicia sesión con tu cuenta registrada o solicita la activación a administración.</Text></View>}<View style={s.onlineCard}><View><Text style={s.panelTitle}>Disponibilidad</Text><Text style={s.subtitle}>{online?"Estás visible para nuevos servicios":"Activa tu disponibilidad"}</Text></View><Pressable disabled={busy} onPress={changeAvailability} style={[s.toggle,online&&s.toggleOn]}><Text style={s.toggleText}>{online?"EN LÍNEA":"OFF"}</Text></Pressable></View>
 <View style={s.mapWrap}><MapCanvas style={s.map} center={region} markers={[{coordinate:driverPoint||origin,title:"Tu ubicación",color:"#246BFE"}]}/><View style={s.mapLabel}><View style={s.dot}/><Text style={s.mapLabelText}>Tu ubicación de trabajo · Cotuí</Text></View></View>
 {APP_ROLE!=="delivery"&&<View style={s.statsRow}><Stat label="Saldo disponible" value={money(Number(wallet?.available_balance_dop||0))}/><Stat label="Comisión plataforma" value="15%"/></View>}
 <Text style={s.section}>Servicios disponibles</Text>{pending.length===0?<Empty title="No hay solicitudes nuevas" body="Los servicios aparecerán cuando estés en línea y un cliente solicite."/>:pending.map(j=><View key={j.id} style={s.panel}><Text style={s.status}>{j.kind==="ride"?"Moto":"Paquete"} · {money(j.price)}</Text><Text style={s.helper}>Recogida: {j.pickup}</Text><Text style={s.helper}>Destino: {j.destination}</Text><Text style={s.helper}>Distancia: {j.distance.toFixed(1)} km · Tu parte: {money(j.driverPayout)}</Text><Pressable style={s.primary} onPress={()=>accept(j)}><Text style={s.primaryText}>Aceptar servicio</Text></Pressable></View>)}
 <Text style={s.section}>Mis servicios</Text>{mine.length===0?<Empty title="Todavía no tienes servicios asignados" body="Cuando aceptes uno, aparecerá aquí."/>:mine.map(j=><DriverJob key={j.id} job={j} pin={pin} setPin={setPin} onAdvance={advance} busy={busy} driverPoint={driverPoint}/>)}
 </ScrollView>}
 {tab==="Billetera"&&APP_ROLE!=="delivery"&&<ScrollView contentContainerStyle={s.content}><Text style={s.title}>Mi billetera</Text><View style={s.panel}><Text style={s.eyebrow}>BALANCE DISPONIBLE</Text><Text style={s.price}>{money(Number(wallet?.available_balance_dop||0))}</Text><Text style={s.helper}>Comisiones reservadas: {money(Number(wallet?.reserved_balance_dop||0))}</Text><Text style={s.panelTitle}>Solicitar recarga</Text><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={topupAmount} onChangeText={setTopupAmount} placeholder="Monto mínimo RD$100" keyboardType="decimal-pad"/><View style={s.serviceRow}><Pressable onPress={()=>setTopupMethod("transferencia")} style={[s.serviceCard,topupMethod==="transferencia"&&s.selected]}><Text style={s.serviceTitle}>Transferencia</Text></Pressable><Pressable onPress={()=>setTopupMethod("efectivo")} style={[s.serviceCard,topupMethod==="efectivo"&&s.selected]}><Text style={s.serviceTitle}>Efectivo</Text></Pressable></View><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={topupReference} onChangeText={setTopupReference} placeholder="Referencia del pago (opcional)"/><Pressable style={s.primary} disabled={busy} onPress={requestWalletTopup}><Text style={s.primaryText}>Enviar solicitud de recarga</Text></Pressable><Text style={s.helper}>Administración revisa el depósito antes de acreditar tu balance.</Text></View><Text style={s.section}>Historial de recargas</Text>{topups.map(x=><View key={x.id} style={s.orderTile}><View style={{flex:1}}><Text style={s.orderTitle}>{money(x.amount_dop)} · {x.payment_method}</Text><Text style={s.orderSub}>{x.status} · {x.payment_reference||"Sin referencia"}</Text></View></View>)}</ScrollView>}
 {tab==="Cuenta"&&<AuthPanel name={name} setName={setName} phone={phone} setPhone={setPhone} email={email} setEmail={setEmail} password={password} setPassword={setPassword} onSignIn={signIn} onSignUp={signUp} onSignOut={signOut} session={session} busy={busy}/>}
 <Bottom items={APP_ROLE==="delivery"?["Inicio","Cuenta"]:["Inicio","Billetera","Cuenta"]} active={tab} onChange={setTab}/></View>}

 {role==="admin"&&<View style={{flex:1}}>{tab==="Inicio"&&<ScrollView contentContainerStyle={s.content}><Text style={s.eyebrow}>CONTROL DE OPERACIONES</Text><Text style={s.title}>Administración</Text><Text style={s.subtitle}>Resumen de solicitudes y repartidores.</Text><View style={s.statsRow}><Stat label="Motos" value={String(adminStats.rides)}/><Stat label="Paquetes" value={String(adminStats.deliveries)}/></View><View style={s.statsRow}><Stat label="Servicios activos" value={String(adminStats.active)}/><Stat label="Repartidores" value={String(adminStats.drivers)}/></View><View style={s.panel}><Text style={s.panelTitle}>Comisiones registradas</Text><Text style={s.price}>{money(adminStats.revenue)}</Text><Text style={s.helper}>La configuración completa de tarifas, revisión de documentos y operación avanzada permanece en el panel web administrativo.</Text></View><Text style={s.section}>Recargas pendientes</Text>{pendingTopups.length===0?<Empty title="No hay recargas pendientes" body="Las solicitudes nuevas aparecerán aquí."/>:pendingTopups.map(t=><View key={t.id} style={s.panel}><Text style={s.panelTitle}>{money(t.amount_dop)} · {t.cg_driver_profiles?.full_name||"Repartidor"}</Text><Text style={s.helper}>{t.payment_method} · {t.payment_reference||"Sin referencia"}</Text><View style={s.statsRow}><Pressable style={[s.primary,{flex:1}]} onPress={()=>reviewTopup(t.id,true)}><Text style={s.primaryText}>Aprobar</Text></Pressable><Pressable style={[s.secondary,{flex:1}]} onPress={()=>reviewTopup(t.id,false)}><Text style={s.secondaryText}>Rechazar</Text></Pressable></View></View>)}<Text style={s.section}>Servicios recientes</Text>{jobs.slice(0,15).map(j=><JobTile key={j.id} job={j} onPress={()=>setActive(j)}/>)}</ScrollView>}
 {tab==="Cuenta"&&<AuthPanel name={name} setName={setName} phone={phone} setPhone={setPhone} email={email} setEmail={setEmail} password={password} setPassword={setPassword} onSignIn={signIn} onSignUp={signUp} onSignOut={signOut} session={session} busy={busy}/>}
 <Bottom items={["Inicio","Cuenta"]} active={tab} onChange={setTab}/></View>}
 </Animated.View></SafeAreaView>;
}


type MapCoordinate={latitude:number;longitude:number};
type MapMarkerData={coordinate:MapCoordinate;title:string;color:string};
function MapCanvas({style,center,markers,route,onLongPress}:{style:any;center:Region;markers:MapMarkerData[];route?:MapCoordinate[];onLongPress?:(coordinate:MapCoordinate)=>void}){
 const zoom=Math.max(10,Math.min(18,Math.log2(360/Math.max(center.latitudeDelta,center.longitudeDelta))));
 const cameraRef=useRef<any>(null);
 useEffect(()=>{cameraRef.current?.easeTo({center:[center.longitude,center.latitude],zoom,duration:350});},[center.latitude,center.longitude,zoom]);
 const routeData=route&&route.length>1?{type:"Feature" as const,properties:{},geometry:{type:"LineString" as const,coordinates:route.map(p=>[p.longitude,p.latitude])}}:null;
 return <Map style={style} mapStyle={MAP_STYLE} attribution compass scaleBar onLongPress={onLongPress?e=>{const point=e.nativeEvent.lngLat;if(point?.length===2)onLongPress({longitude:point[0],latitude:point[1]});}:undefined}>
  <Camera ref={cameraRef} initialViewState={{center:[center.longitude,center.latitude],zoom}}/>
  {routeData&&<GeoJSONSource id="cotui-go-route" data={routeData}><Layer id="cotui-go-route-line" type="line" paint={{"line-color":GREEN,"line-width":4,"line-opacity":0.9}}/></GeoJSONSource>}
  {markers.map((item,index)=><MapMarker key={item.title+index} lngLat={[item.coordinate.longitude,item.coordinate.latitude]} anchor="center"><View style={{alignItems:"center"}}><View style={{width:19,height:19,borderRadius:10,backgroundColor:item.color,borderWidth:3,borderColor:"#FFFFFF",elevation:4}}/><View style={{backgroundColor:"#FFFFFFEE",paddingHorizontal:7,paddingVertical:3,borderRadius:7,marginTop:3}}><Text style={{fontSize:9,fontWeight:"800",color:INK}}>{item.title}</Text></View></View></MapMarker>)}
 </Map>;
}

function JobTile({job,onPress}:{job:Job;onPress:()=>void}){return <Pressable onPress={onPress} style={s.orderTile}><View style={s.orderIcon}><Text>{job.kind==="ride"?"🏍️":"📦"}</Text></View><View style={{flex:1}}><Text style={s.orderTitle}>{job.kind==="ride"?"Moto":"Paquete"} · {money(job.price)}</Text><Text style={s.orderSub} numberOfLines={1}>{job.destination}</Text><Text style={s.orderStatus}>{statusText(job.status)}</Text></View><Text style={s.chevron}>›</Text></Pressable>}
function DriverJob({job,pin,setPin,onAdvance,busy,driverPoint}:{job:Job;pin:string;setPin:(v:string)=>void;onAdvance:(j:Job,next:string)=>void;busy:boolean;driverPoint:any}){const sequence=["accepted","courier_arriving","picked_up","on_the_way","delivered"];const next=sequence[sequence.indexOf(job.status)+1];const pickupCoord=job.pickupLat!=null&&job.pickupLng!=null?{latitude:job.pickupLat,longitude:job.pickupLng}:COTUI;const destCoord=job.destinationLat!=null&&job.destinationLng!=null?{latitude:job.destinationLat,longitude:job.destinationLng}:COTUI;const target=job.kind==="ride"&&job.status==="in_progress"||job.kind==="delivery"&&job.status==="on_the_way"?destCoord:pickupCoord;return <View style={s.panel}><Text style={s.panelTitle}>{job.kind==="ride"?"Viaje en moto":"Entrega de paquete"}</Text><Text style={s.helper}>Recogida: {job.pickup}</Text><Text style={s.helper}>Destino: {job.destination}</Text><Text style={s.helper}>Tarifa {money(job.price)} · Ganancia {money(job.driverPayout)}</Text><View style={s.liveMap}><MapCanvas style={s.map} center={{...target,latitudeDelta:.012,longitudeDelta:.012}} markers={[{coordinate:pickupCoord,title:"Recogida",color:GREEN},{coordinate:destCoord,title:"Destino",color:"#E9A23B"},...(driverPoint?[{coordinate:driverPoint,title:"Tu ubicación",color:"#246BFE"}]:[])]} route={driverPoint?[driverPoint,target]:[pickupCoord,destCoord]}/></View><Pressable style={s.secondary} onPress={()=>Linking.openURL("https://www.google.com/maps/dir/?api=1&destination="+target.latitude+","+target.longitude+"&travelmode=driving")}><Text style={s.secondaryText}>Navegar con Google Maps</Text></Pressable>{job.kind==="ride"&&next==="in_progress"?<><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={pin} onChangeText={setPin} placeholder="PIN de 4 dígitos del pasajero" keyboardType="number-pad" maxLength={4}/><Pressable style={s.primary} disabled={busy||pin.length!==4} onPress={()=>onAdvance(job,"in_progress")}><Text style={s.primaryText}>Verificar PIN e iniciar viaje</Text></Pressable></>:next?<Pressable style={s.primary} disabled={busy} onPress={()=>onAdvance(job,next)}><Text style={s.primaryText}>{next==="courier_arriving"?"Voy a recoger":next==="picked_up"?"Marcar paquete recogido":next==="on_the_way"?"En camino":"Finalizar servicio"}</Text></Pressable>:<Text style={s.status}>{statusText(job.status)}</Text>}</View>}
function Empty({title,body}:{title:string;body:string}){return <View style={s.empty}><Text style={s.emptyIcon}>⌁</Text><Text style={s.panelTitle}>{title}</Text><Text style={s.helper}>{body}</Text></View>}
function Stat({label,value}:{label:string;value:string}){return <View style={s.stat}><Text style={s.statValue}>{value}</Text><Text style={s.statLabel}>{label}</Text></View>}
function AuthPanel({name,setName,phone,setPhone,email,setEmail,password,setPassword,onSignIn,onSignUp,onSignOut,session,busy}:{name:string;setName:(v:string)=>void;phone:string;setPhone:(v:string)=>void;email:string;setEmail:(v:string)=>void;password:string;setPassword:(v:string)=>void;onSignIn:()=>void;onSignUp:()=>void;onSignOut:()=>void;session:any;busy:boolean}){return <KeyboardAvoidingView behavior={Platform.OS==="ios"?"padding":undefined} style={{flex:1}}><ScrollView contentContainerStyle={s.content}><Text style={s.title}>Tu cuenta</Text><Text style={s.subtitle}>Accede a tus servicios Cotuí Go.</Text><View style={s.panel}>{session?<><Text style={s.panelTitle}>Sesión activa</Text><Text style={s.helper}>{session.user?.email}</Text><Pressable style={s.secondary} onPress={onSignOut}><Text style={s.secondaryText}>Cerrar sesión</Text></Pressable></>:<><Text style={s.panelTitle}>Crear cuenta o entrar</Text><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={name} onChangeText={setName} placeholder="Nombre completo"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={phone} onChangeText={setPhone} placeholder="Teléfono" keyboardType="phone-pad"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={email} onChangeText={setEmail} placeholder="Correo electrónico" autoCapitalize="none" keyboardType="email-address"/><TextInput style={s.input} placeholderTextColor="#667085" selectionColor={GREEN} value={password} onChangeText={setPassword} placeholder="Contraseña" secureTextEntry/><Pressable style={s.primary} onPress={onSignIn} disabled={busy}>{busy?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>Entrar</Text>}</Pressable><Pressable style={s.secondary} onPress={onSignUp} disabled={busy}><Text style={s.secondaryText}>Crear cuenta nueva</Text></Pressable><Text style={s.helper}>Para trabajar como repartidor debes completar el registro y la aprobación de documentos desde el portal de conductores.</Text></>}</View></ScrollView></KeyboardAvoidingView>}
function Bottom({items,active,onChange}:{items:string[];active:string;onChange:(v:string)=>void}){return <View style={s.bottom}>{items.map((x,i)=><Pressable key={x} onPress={()=>onChange(x)} style={s.bottomItem}><Text style={[s.bottomIcon,active===x&&{color:GREEN}]}>{["⌂","◷","◉"][i]||"•"}</Text><Text style={[s.bottomText,active===x&&{color:GREEN,fontWeight:"800"}]}>{x}</Text></Pressable>)}</View>}
